    status,
    headers: { "Content-Type": "application/json" },
  });
}

const CONFIG = {
  conferenceName: "Konferenca 2027",
  consent: { id: "personal-data", text: "Soglašam." },
  captcha: { mode: "test", siteKey: "" },
};

describe("App", () => {
